import MobileSelect from './MobileSelect'
import DebtAmount from './DebtAmount'
import { useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { executeTreatment, getCustomerOverview, listResource, undoTreatmentExecution } from '../api/resources'
import { dateOnly, formatCurrency, formatSpaDate, today } from '../utils/format'
import { useBranch } from './AppShell'
import { useAuth } from '../auth/AuthProvider'
import RoleStaffPicker from './RoleStaffPicker'
import CustomerProfile from './CustomerProfile'
import SkinImageAlbum from './SkinImageAlbum'
import SignaturePad from './SignaturePad'
import ConfirmDialog from './ConfirmDialog'
import TreatmentSessionDialog from './TreatmentSessionDialog'
import TreatmentCardPanel from './TreatmentCardPanel'
import { canExecuteCard, isTreatmentComplete } from '../utils/todayTreatments'
import './CustomerOverview.css'

export default function CustomerOverview({ customerId, overview, onOverview }) {
  const { user } = useAuth(), { branchId } = useBranch(), manager = user.system_role === 'MANAGER', qc = useQueryClient()
  const [expanded, setExpanded] = useState(null), [active, setActive] = useState(null), [message, setMessage] = useState(''), [messageType, setMessageType] = useState('success')
  const [confirmUnsigned, setConfirmUnsigned] = useState(false)
  const [sessionEditor, setSessionEditor] = useState(null)
  const branches = useQuery({ queryKey: ['branches', 'customer-overview'], queryFn: () => listResource('branches', {}, 1, 100).then(r => r ?? { data: [] }) })
  const execution = useMutation({ mutationFn: executeTreatment, onSuccess: async () => { setActive(null); setMessageType('success'); setMessage('Đã ghi nhận một buổi thực hiện.'); qc.invalidateQueries({ queryKey: ['treatments'] }); qc.invalidateQueries({ queryKey: ['dashboard-treatments'] }); try { onOverview(await getCustomerOverview(customerId)) } catch (error) { setMessageType('error'); setMessage(`Đã ghi nhận buổi; không tải lại được hồ sơ: ${error.message}. Không xác nhận lại.`) } }, onError: error => { setMessageType('error'); setMessage(`Chưa xác nhận được trạng thái buổi: ${error.message}. Kiểm tra lịch sử trước khi thử lại.`) } })
  const submitExecution = (allowUnsigned = false) => {
    if (!active || execution.isPending || (manager && !active.branch)) return
    if (new TextEncoder().encode(active.note || '').length > 65535) {
      setMessageType('error'); setMessage('Ghi chú buổi thực hiện tối đa 65535 byte UTF-8.'); return
    }
    if (!active.signature && !allowUnsigned) { setConfirmUnsigned(true); return }
    setConfirmUnsigned(false)
    setMessage('')
    execution.mutate({
      treatment_id: active.id,
      ...(manager ? { branch_id: Number(active.branch) } : {}),
      ...(manager && active.execution_date ? { execution_date: active.execution_date } : {}),
      staffs: active.staffs,
      ...(active.note?.trim() ? { note: active.note.trim() } : {}),
      ...(active.signature ? { customer_signature_svg: active.signature } : {})
    })
  }
  if (!overview) return <p>Đang tải lịch sử khách hàng...</p>
  const { customer, timeline = [] } = overview
  return <section className="customer-overview">
    <div className="customer-identity"><strong>{customer.fullname}</strong><span>{customer.phone_number}</span><span>{customer.address || 'Chưa có địa chỉ'}</span><span>Ví: {formatCurrency(customer.wallet_balance)}</span><span>Nợ: <DebtAmount value={customer.total_debt} /></span></div>
    <div className="customer-overview-columns"><div className="customer-timeline customer-panel">
    {message && <p role={messageType === 'error' ? 'alert' : 'status'} className={messageType === 'error' ? 'form-alert' : 'success-alert'}>{message}</p>}
    <h3>Lịch sử mua và chăm sóc</h3>
    {!timeline.length && <p className="small-muted">Khách chưa có giao dịch hoặc liệu trình.</p>}
    {timeline.map((entry, index) => {
      const purchase = entry.type === 'purchase' ? entry.item : null
      const treatment = purchase?.treatment || (entry.type === 'treatment' ? entry.treatment : null)
      const todayExecutions = treatment?.histories?.filter(history => dateOnly(history.execution_date) === today()).length || 0
      const selectedForToday = active?.id === treatment?.id
      if (!purchase && !treatment) return null
       return <div className="timeline-row" key={`${entry.type}-${purchase?.invoice_item_id || treatment.id}-${index}`}><time>{formatSpaDate(entry.date)}</time><div className={`timeline-main timeline-purchase-card ${purchase && Number(purchase.is_product) ? 'is-product' : 'is-service'} ${treatment && isTreatmentComplete(treatment) ? 'is-completed' : ''}`}>
        <span className="timeline-kind">{purchase && Number(purchase.is_product) ? 'Sản phẩm đã mua' : 'Dịch vụ đã mua'}</span>
        {purchase && <><strong>{purchase.product_name}</strong><small>Hóa đơn #{purchase.invoice_id} · {purchase.quantity} × {formatCurrency(purchase.unit_price)}</small><div className="timeline-purchase-total"><span>Thành tiền</span><strong>{formatCurrency(purchase.final_price)}</strong></div></>}
        {treatment && <TreatmentCardPanel
          card={{ ...treatment, customer_name: customer.fullname }}
          branchId={branchId || user.branch_id}
          branches={branches.data?.data}
          embedded
          onUpdated={async () => {
            onOverview(await getCustomerOverview(customerId));
            setMessage('Đã ghi nhận buổi thực hiện thành công.');
            setMessageType('success');
          }}
          onUndo={async id => {
            try {
              await undoTreatmentExecution(id);
              onOverview(await getCustomerOverview(customerId));
            } catch (error) {
              setMessageType('error');
              setMessage(error.message);
            }
          }}
        />}
      </div></div>
    })}
    </div><aside className="customer-profile-column"><CustomerProfile customer={customer} /><SkinImageAlbum key={customerId} customerId={customerId} /></aside></div>
    {confirmUnsigned && <ConfirmDialog title="Ghi nhận buổi chưa có chữ ký?" message="Bạn có chắc chắn muốn ghi nhận buổi mà không có chữ ký khách hàng? Có thể ký bổ sung vào buổi này sau khi ghi nhận." cancelLabel="Quay lại ký" confirmLabel="Ghi nhận không có chữ ký" pending={execution.isPending} onCancel={() => setConfirmUnsigned(false)} onConfirm={() => submitExecution(true)} />}
    {sessionEditor && <TreatmentSessionDialog history={sessionEditor.history} card={sessionEditor.card} user={user} onClose={() => setSessionEditor(null)} onUpdated={async () => onOverview(await getCustomerOverview(customerId))} />}
  </section>
}

import { Fragment, useState } from 'react'
import { useMutation, useQueries, useQuery, useQueryClient } from '@tanstack/react-query'
import { useBranch } from './AppShell'
import { useAuth } from '../auth/AuthProvider'
import { canUndoTreatmentExecution } from '../auth/permissions'
import { assignTreatmentStaffs, executeTreatment, getResource, listResource, undoTreatmentExecution } from '../api/resources'
import { today } from '../utils/format'
import RoleStaffPicker from './RoleStaffPicker'
import ConfirmDialog from './ConfirmDialog'
import MobileSelect from './MobileSelect'
import { Pencil } from 'lucide-react'
import { canFollowUpTreatmentHistory } from '../auth/permissions'
import { formatSpaDate } from '../utils/format'
import TreatmentSessionDialog from './TreatmentSessionDialog'
import { canExecuteCard, todayTreatmentRows, treatmentCards } from '../utils/todayTreatments'
import TreatmentGroupSignature from './TreatmentGroupSignature'
import Pagination from './Pagination'
import './TodayTreatments.css'

export default function TodayTreatments() {
  const { branchId } = useBranch(), { user } = useAuth(), qc = useQueryClient()
  const manager = user.system_role === 'MANAGER'
  const [executionDate, setExecutionDate] = useState(today)
  const [sessionEditor, setSessionEditor] = useState(null)
  const [page, setPage] = useState(1), [selected, setSelected] = useState(null), [undo, setUndo] = useState(null)
  const [staffs, setStaffs] = useState([]), [executionBranch, setExecutionBranch] = useState(''), [message, setMessage] = useState(''), [messageType, setMessageType] = useState('success')
  // Treatment list dates filter creation, not execution. Scan all cards to find today's histories.
  const query = useQuery({ queryKey: ['dashboard-treatments', 'all', branchId], queryFn: async () => {
    // branchId on treatments means ORIGINAL invoice branch, not execution branch.
    const filters = {}
    const first = await listResource('treatments', filters, 1, 100)
    const rest = await Promise.all(Array.from({ length: Math.max(0, first.totalPages - 1) }, (_, i) => listResource('treatments', filters, i + 2, 100)))
    return [first, ...rest].flatMap(result => result.data)
  } })
  const staffBranch = manager ? (selected ? executionBranch : branchId) : branchId
  const employees = useQuery({ queryKey: ['staffs', 'today', staffBranch], queryFn: () => listResource('staffs', staffBranch ? { branchId: staffBranch } : {}, 1, 100), enabled: !manager || Boolean(staffBranch) })
  const branches = useQuery({ queryKey: ['branches', 'dashboard-treatment'], queryFn: () => listResource('branches', {}, 1, 100), enabled: manager })
  const roles = useQuery({ queryKey: ['roles', 'staff-picker'], queryFn: () => listResource('roles', {}, 1, 100) })
  function staffSummary(history) {
    return (history.staffs || []).map(staff => {
      const role = staff.role_name || staff.role_type || roles.data?.data?.find(role => Number(role.id) === Number(staff.role_id))?.name || ''
      return `${role.replace(/^bác sĩ/i, 'BS').replace(/^kỹ thuật viên/i, 'KTV')} ${staff.staff_name || staff.fullname || `#${staff.staff_id}`}`.trim()
    }).join(' · ')
  }
  const allCards = query.data || []
  const cardDetails = useQueries({ queries: allCards.map(card => ({ queryKey: ['dashboard-treatments', 'detail', card.id], queryFn: () => getResource('treatments', card.id), staleTime: 15_000 })) })
  const currentDay = today()
  const rows = todayTreatmentRows(allCards, cardDetails, currentDay, branchId)

  // Gom các dòng theo khối lượt thực hiện (block) để không bao giờ bị cắt đôi giữa 2 trang
  const blocks = []
  let currentBlock = null
  for (const row of rows) {
    if (row.group) {
      currentBlock = { groupRow: row, childRows: [] }
      blocks.push(currentBlock)
    } else if (currentBlock && row.child) {
      currentBlock.childRows.push(row)
    } else {
      currentBlock = null
      blocks.push({ groupRow: null, childRows: [row] })
    }
  }

  const PAGE_SIZE = 10
  const pages = Math.max(1, Math.ceil(blocks.length / PAGE_SIZE))
  const currentPage = Math.min(page, pages)
  const startIdx = (currentPage - 1) * PAGE_SIZE
  const endIdx = Math.min(startIdx + PAGE_SIZE, blocks.length)
  const visibleBlocks = blocks.slice(startIdx, endIdx)
  const mutation = useMutation({
    mutationFn: async ({ card, historyId, assigned, branch, execution_date }) => {
      if (historyId) return assignTreatmentStaffs(historyId, assigned)
      const created = await executeTreatment({ treatment_id: card.id, ...(manager ? { branch_id: Number(branch), execution_date } : {}), staffs: [] })
      if (assigned.length) {
        try { await assignTreatmentStaffs(created.treatmentHistoryId, assigned) }
        catch (error) { throw new Error(`Đã ghi nhận buổi #${created.treatmentHistoryId} nhưng chưa gán được nhân viên: ${error.message}. Mở lại thẻ để gán, không tick lần nữa.`) }
      }
      return created
    },
    onSuccess: () => { qc.invalidateQueries({ queryKey: ['dashboard-treatments'] }); qc.invalidateQueries({ queryKey: ['treatments'] }); qc.invalidateQueries({ queryKey: ['commissions'] }); setMessageType('success'); setMessage('Đã ghi nhận buổi và lưu nhân viên thực hiện.'); setSelected(null) },
    onError: err => { qc.invalidateQueries({ queryKey: ['dashboard-treatments'] }); setMessageType('error'); setMessage(err.message) },
  })
  const undoMutation = useMutation({ mutationFn: id => {
    const history = cardDetails.flatMap(detail => detail.data ? treatmentCards(detail.data).flatMap(card => card.histories || []) : []).find(history => history.id === id)
    if (!canUndoTreatmentExecution(user, history)) throw new Error('Bạn không có quyền hoàn tác buổi thực hiện này.')
    return undoTreatmentExecution(id)
  }, onSuccess: () => { qc.invalidateQueries({ queryKey: ['dashboard-treatments'] }); qc.invalidateQueries({ queryKey: ['treatments'] }); qc.invalidateQueries({ queryKey: ['commissions'] }); setUndo(null); setSelected(null); setMessageType('success'); setMessage('Đã hoàn tác buổi hôm nay.') }, onError: err => { setUndo(null); setMessageType('error'); setMessage(err.message) } })
  function pick(card, history) {
    if (selected?.card.id === card.id && selected.historyId === history?.id) { setSelected(null); setMessage(''); return }
    setSelected({ card, historyId: history?.id })
    setExecutionDate(today())
    setExecutionBranch(String(history?.branch_id || branchId || card.branch_id || ''))
    setStaffs((history?.staffs || []).map(s => ({ staff_id: Number(s.staff_id) })))
    setMessage('')
  }
  function save() {
    if (!selected.historyId && !canExecuteCard(selected.card)) return setMessage('Thẻ đã hết buổi hoặc đã đóng.')
    if (manager && !selected.historyId && !Number(executionBranch)) return setMessage('Chọn cơ sở thực hiện ngay tại dòng này trước khi xác nhận.')
    if (manager && !selected.historyId && !executionDate) return setMessage('Chọn ngày thực hiện.')
    if (employees.isLoading || (manager && !employees.data)) return setMessage('Đang tải danh sách nhân viên. Vui lòng chờ trước khi xác nhận.')
    if (employees.isError) return setMessage(`Không tải được danh sách nhân viên: ${employees.error.message}`)
    if (employees.data?.totalPages > 1) return setMessage('Danh sách nhân viên vượt 100 người. Vui lòng kiểm tra phạm vi danh sách trước khi gán.')
    setMessage('')
    mutation.mutate({ ...selected, assigned: staffs, branch: executionBranch, execution_date: executionDate })
  }
  return <section className="section-card today-treatments">
    <div className="surface-heading"><div><span className="eyebrow">KHÁCH LÀM DỊCH VỤ</span><h2>Khách hàng hôm nay</h2></div></div>
    <p className="small-muted">Thẻ tạo hôm nay hoặc có buổi thực hiện hôm nay. Tick để ghi nhận, bấm tên nhân viên để sửa, bỏ tick để hoàn tác.{!manager && ' Nhân viên chỉ được hoàn tác buổi có ngày thực hiện và ngày tạo đều là hôm nay, tại cơ sở của mình.'}</p>
    {message && !selected && <p role={messageType === 'error' ? 'alert' : 'status'} className={messageType === 'error' ? 'form-alert' : 'success-alert'}>{message}</p>}
    {query.isError ? <p className="form-alert">Không tải được thẻ: {query.error.message}</p> : query.isLoading || cardDetails.some(d => d.isLoading) ? <p>Đang tải thẻ...</p> : blocks.length ? <>
      <div className="table-scroll"><table><thead><tr><th>Khách hàng</th><th>Dịch vụ</th><th>Đã làm hôm nay</th><th>Nhân viên thực hiện</th><th>Chữ ký khách hàng</th></tr></thead>
      {visibleBlocks.map(block => (
        <tbody className="today-visit" key={block.groupRow ? `block-group-${block.groupRow.card.id}-${block.groupRow.groupKey || '0'}` : `block-standalone-${block.childRows[0]?.card.id}-${block.childRows[0]?.history?.id || 'new'}`}>
          {block.groupRow && (() => {
            const { card, groupKey, groupTitle, sessions: rowSessions } = block.groupRow
            const sessions = rowSessions || []
            return <tr key={`group-${card.id}-${groupKey || '0'}`} className="today-treatment-group">
              <td data-label="Khách hàng"><strong>{card.customer_name}</strong></td>
              <td colSpan={3}>
                <div className="today-group-heading">
                  <strong>{groupTitle || card.product_name}</strong>
                  <small>{sessions.length ? `${sessions.length} dịch vụ` : `${card.children?.length || 0} dịch vụ`}</small>
                </div>
              </td>
              <td data-label="Chữ ký khách hàng">
                {sessions.length ? <TreatmentGroupSignature card={card} sessions={sessions} user={user} /> : '—'}
              </td>
            </tr>
          })()}
          {block.childRows.map(row => {
            const { card, detail: cardQuery, history, multiple, child, groupKey } = row
            const active = selected?.card.id === card.id && selected.historyId === history?.id
            const canUndo = canUndoTreatmentExecution(user, history)
            const signed = Boolean(history?.customer_signature_svg || history?.customer_signed_at)
            const allowed = canFollowUpTreatmentHistory(user, history)
            const suffix = multiple ? ` · Buổi #${history?.id}` : ''
            return <Fragment key={`row-${card.id}-${history?.id || 'new'}-${groupKey || 'standalone'}`}>
              <tr className={child ? 'today-treatment-child' : 'today-treatment-standalone'} data-history-id={history?.id}>
                <td data-label="Khách hàng">{child ? null : card.customer_name}</td>
                <td data-label="Dịch vụ"><span className={child ? 'today-child-service' : undefined}>{card.product_name}</span></td>
                <td data-label="Đã làm hôm nay"><input type="checkbox" aria-label={`Đã làm ${card.customer_name} - ${card.product_name}${suffix}`} checked={Boolean(history) || (active && !selected.historyId)} disabled={(Boolean(history) && !canUndo) || cardQuery?.isLoading || cardQuery?.isError || (!history && !canExecuteCard(card)) || mutation.isPending || undoMutation.isPending} onChange={e => e.target.checked ? pick(card, history) : canUndo && setUndo(history.id)} /></td>
                <td data-label="Nhân viên thực hiện">
                  {cardQuery?.isError ? 'Không tải được lịch sử' : active ? 'Đang chọn nhân viên bên dưới' : history ? <button type="button" className="text-action" onClick={() => pick(card, history)} aria-label={`Sửa nhân viên ${card.customer_name} - ${card.product_name}${suffix}`}>{staffSummary(history) || 'Chưa gán NV'}</button> : 'Chưa thực hiện'}
                </td>
                <td data-label="Chữ ký khách hàng">
                  {child ? null : cardQuery?.isError ? 'Không tải được lịch sử' : history ? <div className="today-session-signatures"><div className="today-signature-preview">{history.customer_signature_svg && <img src={`data:image/svg+xml;charset=utf-8,${encodeURIComponent(history.customer_signature_svg)}`} alt={`Chữ ký buổi #${history.id}`} />}<small>{signed ? 'Đã ký' : 'Chưa ký'}</small></div><button type="button" className="session-followup-button" aria-label={`${allowed ? 'Ghi chú và chữ ký' : 'Xem buổi'} #${history.id} - ${card.customer_name}`} onClick={() => setSessionEditor({ card, history })}><Pencil size={12} aria-hidden="true" />{allowed ? signed ? 'Ghi chú / Xem' : 'Ghi chú / Ký' : 'Xem'}</button></div> : '—'}
                </td>
              </tr>
              {active && <tr className="today-staff-row"><td colSpan={5}><div className="treatment-actions today-staff-actions">
                {manager && !selected.historyId && <label className="field">Cơ sở thực hiện<MobileSelect aria-label="Cơ sở thực hiện" value={executionBranch} onChange={e => { setExecutionBranch(e.target.value); setStaffs([]); setMessage('') }}><option value="">Chọn cơ sở</option>{branches.data?.data?.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}</MobileSelect></label>}
                {manager && !selected.historyId && <label className="field">Ngày thực hiện<input type="date" required value={executionDate} onChange={e => setExecutionDate(e.target.value)} /></label>}
                <RoleStaffPicker selected={staffs} onChange={setStaffs} branchId={staffBranch || 'required'} /><button type="button" className="btn primary" disabled={mutation.isPending || !navigator.onLine} onClick={save}>{mutation.isPending ? 'Đang lưu...' : 'Xác nhận'}</button><button type="button" className="btn secondary" onClick={() => { setSelected(null); setMessage('') }}>Hủy</button>
              </div>{branches.isError && manager && !selected.historyId && <p className="form-alert">Không tải được cơ sở: {branches.error.message}</p>}{message && <p role="alert" className="form-alert">{message}</p>}</td></tr>}
            </Fragment>
          })}
        </tbody>
      ))}
      </table></div>
      <Pagination
        page={currentPage}
        totalPages={pages}
        totalItems={blocks.length}
        pageSize={PAGE_SIZE}
        onChange={setPage}
        label="lượt khách"
      />
    </> : <p className="small-muted">Chưa có khách làm dịch vụ hôm nay.</p>}
    {undo && <ConfirmDialog title="Hoàn tác buổi hôm nay?" message="Buổi thực hiện và tiền công đã ghi nhận sẽ bị hoàn tác." pending={undoMutation.isPending} onCancel={() => setUndo(null)} onConfirm={() => undoMutation.mutate(undo)} />}
    {sessionEditor && <TreatmentSessionDialog history={sessionEditor.history} card={sessionEditor.card} user={user} onClose={() => setSessionEditor(null)} />}
  </section>
}

import { useRef, useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { executeTreatment, listResource } from '../api/resources'
import { canExecuteCard, treatmentCards } from '../utils/todayTreatments'
import { today } from '../utils/format'
import InvoiceChildStaffPicker from './InvoiceChildStaffPicker'
import MobileSelect from './MobileSelect'
import SignaturePad from './SignaturePad'
import ConfirmDialog from './ConfirmDialog'

export default function TreatmentExecution({ card, user, branchId, onUpdated, onCancel, initialSelectedIds = [], embedded = false }) {
  const manager = user?.system_role === 'MANAGER', grouped = Boolean(card.children?.length)
  const showDate = Boolean(manager)
  const available = treatmentCards(card).filter(canExecuteCard)

  const initialSelected = {}
  if (grouped) {
    if (initialSelectedIds?.length > 0) {
      initialSelectedIds.forEach(id => {
        if (available.some(item => item.id === id)) initialSelected[id] = []
      })
    }
  } else if (available[0]) {
    initialSelected[available[0].id] = []
  }

  const [selected, setSelected] = useState(initialSelected)
  const [branch, setBranch] = useState(branchId || user?.branch_id || ''), [date, setDate] = useState(today())
  const [note, setNote] = useState(''), [signature, setSignature] = useState(null), [metadataOpen, setMetadataOpen] = useState(false)
  const [pending, setPending] = useState(false), [blocked, setBlocked] = useState(false), [message, setMessage] = useState(''), [confirm, setConfirm] = useState(false)
  const busy = useRef(false), qc = useQueryClient()
  const branches = useQuery({ queryKey: ['branches', 'treatment-picker'], queryFn: () => listResource('branches', {}, 1, 100).then(r => r ?? { data: [] }),  })
  const chosen = available.filter(item => Object.hasOwn(selected, item.id))

  async function submit(unsigned = false) {
    if (busy.current || blocked || !navigator.onLine) return
    if (!chosen.length || !branch || !date) { setMessage('Chọn dịch vụ, cơ sở và ngày thực hiện.'); return }
    if (new TextEncoder().encode(note).length > 65535) { setMessage('Ghi chú tối đa 65535 byte UTF-8.'); return }
    if (!signature && !unsigned) { setConfirm(true); return }
    busy.current = true; setPending(true); setConfirm(false); setMessage('')
    const done = []
    try {
      for (let i = 0; i < chosen.length; i++) {
        const item = chosen[i]
        const payload = {
          treatment_id: item.id,
          staffs: selected[item.id],
          ...(manager ? { branch_id: Number(branch), execution_date: date } : {}),
          ...(note.trim() ? (i === 0 ? { note: note.trim() } : {}) : {}),
          ...(signature ? { customer_signature_svg: signature } : {}),
        }
        await executeTreatment(payload)
        done.push(item.product_name)
      }
      setBlocked(true)
      await onUpdated?.()
      onCancel?.()
    } catch (error) {
      setBlocked(true)
      setMessage(`${done.length ? `Đã ghi nhận: ${done.join(', ')}. ` : ''}${error.message}. Dừng gửi để tránh trừ buổi trùng. Kiểm tra lịch sử trước khi mở lại.`)
    } finally {
      await Promise.allSettled(['treatments', 'dashboard-treatments', 'appointments'].map(key => qc.invalidateQueries({ queryKey: [key] })))
      busy.current = false; setPending(false)
    }
  }

  return <div className={`treatment-execution-form ${grouped ? 'is-grouped-form' : 'is-single-form'}`}>
    <fieldset disabled={pending || blocked}>
      {grouped ? (
        <div className="treatment-execution-split">
          <div className="treatment-execution-left-col">
            {available.map(item => <div className="treatment-child-execution is-child" key={item.id}>
              <div className="treatment-child-execution-row">
                <label className="treatment-child-label">
                  <input
                    aria-label={item.product_name}
                    type="checkbox"
                    checked={Object.hasOwn(selected, item.id)}
                    onChange={event => setSelected(current => {
                      const next = { ...current };
                      if (event.target.checked) next[item.id] = [];
                      else delete next[item.id];
                      return next;
                    })}
                  />
                  <span className="treatment-child-name">{item.product_name}</span>
                </label>
                <span className="treatment-session-count">{item.remaining_sessions === null ? 'Trọn đời' : `${item.remaining_sessions}/${item.total_sessions} buổi`}</span>
                {Object.hasOwn(selected, item.id) ? (
                  <div className="treatment-child-staff-inline">
                    <InvoiceChildStaffPicker name={item.product_name} selected={selected[item.id]} onChange={staffs => setSelected(current => ({ ...current, [item.id]: staffs }))} branchId={branch || 'required'} />
                  </div>
                ) : (
                  <span className="treatment-child-staff-placeholder" aria-hidden="true" />
                )}
              </div>
            </div>)}
          </div>
          <div className="treatment-execution-right-col">
            {manager && <div className={`treatment-execution-manager-row${showDate ? '' : ' no-date'}`}>
              <label className="field compact-field branch-field"><span>Cơ sở thực hiện</span><MobileSelect value={branch} onChange={event => { setBranch(event.target.value); setSelected(current => Object.fromEntries(Object.keys(current).map(id => [id, []]))) }}><option value="">Chọn cơ sở</option>{branches.data?.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</MobileSelect></label>
              {showDate && <label className="field compact-field date-field"><span>Ngày thực hiện</span><input type="date" required value={date} onChange={event => setDate(event.target.value)} /></label>}
            </div>}
            <div className="treatment-session-tools">
              <button type="button" className={`session-followup-button${note.trim() ? ' has-value' : ''}`} onClick={() => setMetadataOpen(open => !open)}>{metadataOpen ? 'Ẩn ghi chú' : note.trim() ? 'Ghi chú ✓' : 'Ghi chú'}</button>
              <span className={`treatment-signature-state${signature ? ' has-value' : ''}`}>{signature ? 'Đã ký nháp' : 'Chưa ký'}</span>
            </div>
            {metadataOpen && <label className="field treatment-execution-note">Ghi chú buổi thực hiện<textarea rows={2} value={note} onChange={event => setNote(event.target.value)} placeholder="Lưu ý cho lần thực hiện này…" /></label>}
            <div className="treatment-execution-signature"><SignaturePad customerName={card.customer_name} productName={card.product_name} disabled={pending || blocked} onChange={setSignature} /></div>
          </div>
        </div>
      ) : (
        /* Thẻ đơn (như pnp): Cho hết lên 1 dòng ngang */
        <div className="treatment-single-execution-row">
          {manager && <div className={`treatment-execution-manager-row is-single-manager${showDate ? '' : ' no-date'}`}>
            <label className="field compact-field branch-field"><span>Cơ sở thực hiện</span><MobileSelect aria-label="Cơ sở thực hiện" value={branch} onChange={event => { setBranch(event.target.value); setSelected(current => Object.fromEntries(Object.keys(current).map(id => [id, []]))) }}><option value="">Chọn cơ sở</option>{branches.data?.data?.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</MobileSelect></label>
            {showDate && <label className="field compact-field date-field"><span>Ngày thực hiện</span><input aria-label="Ngày thực hiện" type="date" required value={date} onChange={event => setDate(event.target.value)} /></label>}
          </div>}
          {available[0] && Object.hasOwn(selected, available[0].id) && (
            <div className="treatment-single-staff">
              <InvoiceChildStaffPicker name={available[0].product_name} selected={selected[available[0].id]} onChange={staffs => setSelected({ [available[0].id]: staffs })} branchId={branch || 'required'} />
            </div>
          )}
          <button type="button" className={`session-followup-button${note.trim() ? ' has-value' : ''}`} onClick={() => setMetadataOpen(open => !open)}>{metadataOpen ? 'Ẩn ghi chú' : note.trim() ? 'Ghi chú ✓' : 'Ghi chú'}</button>
          <div className="treatment-execution-signature"><SignaturePad customerName={card.customer_name} productName={card.product_name} disabled={pending || blocked} onChange={setSignature} /></div>
          <div className="treatment-single-actions">
            <button type="button" className="btn secondary" disabled={pending} onClick={onCancel}>Đóng</button>
            <button type="button" className="btn primary" disabled={pending || blocked || !chosen.length || !navigator.onLine} onClick={() => submit()}>{pending ? 'Đang ghi nhận...' : manager ? 'Xác nhận' : 'Xác nhận hôm nay'}</button>
          </div>
        </div>
      )}

      {!grouped && metadataOpen && (
        <label className="field treatment-execution-note treatment-single-note">Ghi chú buổi thực hiện<textarea rows={2} value={note} onChange={event => setNote(event.target.value)} placeholder="Lưu ý cho lần thực hiện này…" /></label>
      )}
    </fieldset>

    {message && <p role="status" className="session-dialog-message">{message}</p>}
    {grouped && <div className="treatment-execution-actions"><button type="button" className="btn secondary" disabled={pending} onClick={onCancel}>Đóng</button><button type="button" className="btn primary" disabled={pending || blocked || !chosen.length || !navigator.onLine} onClick={() => submit()}>{pending ? 'Đang ghi nhận...' : manager ? 'Xác nhận' : 'Xác nhận hôm nay'}</button></div>}
    {confirm && <ConfirmDialog title="Ghi nhận buổi chưa có chữ ký?" message="Bạn có chắc chắn muốn ghi nhận những dịch vụ đã chọn mà không có chữ ký khách hàng? Có thể ký bổ sung sau." cancelLabel="Quay lại ký" confirmLabel="Ghi nhận không có chữ ký" onCancel={() => setConfirm(false)} onConfirm={() => submit(true)} />}
  </div>
}

import { dateOnly, formatSpaDate } from './format'

export function treatmentCards(root) {
  return [root, ...(root.children || []).flatMap(treatmentCards)]
}

export function todayTreatmentRows(roots, details, day, branchId) {
  const matchesBranch = id => !branchId || Number(id) === Number(branchId)
  return roots.flatMap((root, index) => {
    const detail = details[index]
    const card = { ...root, ...detail?.data }
    const cards = treatmentCards(card)
    const historiesFor = item => (item.histories || []).filter(history => dateOnly(history.execution_date) === day && matchesBranch(history.branch_id) && !history.deleted_at)

    const wasCreatedToday = dateOnly(card.created_at) === day && (!card.branch_id || matchesBranch(card.branch_id))
    const hasHistoriesToday = cards.some(item => historiesFor(item).length > 0)
    if (!wasCreatedToday && !hasHistoriesToday) return []

    // Combo liệu trình có các liệu trình con
    if (card.children?.length) {
      const todayGroups = treatmentHistoryGroups(card).filter(g => g.day === day && matchesBranch(g.branch_id))
      const sortedGroups = [...todayGroups].sort((a, b) => {
        const tA = new Date(a.firstCreatedAt || a.day).getTime()
        const tB = new Date(b.firstCreatedAt || b.day).getTime()
        return tA - tB
      })

      const unperformedChildren = cards.slice(1).filter(child => historiesFor(child).length === 0)

      // Chưa có lượt thực hiện nào hôm nay nhưng thẻ tạo hôm nay
      if (sortedGroups.length === 0) {
        const groupRow = {
          card,
          detail,
          group: true,
          groupKey: `${card.id}-new`,
          groupTitle: card.product_name,
          sessions: []
        }
        const childRows = cards.slice(1).map(child => ({
          card: { ...child, customer_name: card.customer_name, branch_id: child.branch_id ?? card.branch_id },
          detail,
          history: null,
          child: true,
          groupKey: `${card.id}-new`
        }))
        return [groupRow, ...childRows]
      }

      // Có đúng 1 nhóm thực hiện hôm nay
      if (sortedGroups.length === 1) {
        const g = sortedGroups[0]
        const groupRow = {
          card,
          detail,
          group: true,
          groupKey: g.key,
          groupTitle: card.product_name,
          sessions: g.sessions,
          signatureSvg: g.signatureSvg
        }
        const executedRows = g.sessions.map(({ card: childCard, history }) => ({
          card: childCard,
          detail,
          history,
          child: true,
          groupKey: g.key
        }))
        const unperformedRows = unperformedChildren.map(child => ({
          card: { ...child, customer_name: card.customer_name, branch_id: child.branch_id ?? card.branch_id },
          detail,
          history: null,
          child: true,
          groupKey: g.key
        }))
        return [groupRow, ...executedRows, ...unperformedRows]
      }

      // Có nhiều lượt thực hiện hôm nay (khách đến làm nhiều lần) -> tách riêng từng lượt
      const result = []
      sortedGroups.forEach((g) => {
        const title = card.product_name
        result.push({
          card,
          detail,
          group: true,
          groupKey: g.key,
          groupTitle: title,
          sessions: g.sessions,
          signatureSvg: g.signatureSvg
        })
        g.sessions.forEach(({ card: childCard, history }) => {
          result.push({
            card: childCard,
            detail,
            history,
            child: true,
            groupKey: g.key
          })
        })
      })

      // Nếu có các dịch vụ con chưa từng làm hôm nay và thẻ tạo hôm nay, tách nhóm chưa thực hiện
      if (unperformedChildren.length > 0 && wasCreatedToday) {
        result.push({
          card,
          detail,
          group: true,
          groupKey: `${card.id}-unperformed`,
          groupTitle: `${card.product_name} · Chưa thực hiện hôm nay`,
          sessions: []
        })
        unperformedChildren.forEach(child => {
          result.push({
            card: { ...child, customer_name: card.customer_name, branch_id: child.branch_id ?? card.branch_id },
            detail,
            history: null,
            child: true,
            groupKey: `${card.id}-unperformed`
          })
        })
      }

      return result
    }

    // Thẻ đơn (không có liệu trình con)
    const histories = historiesFor(card)
    const inherited = { ...card, customer_name: card.customer_name, branch_id: card.branch_id }
    return histories.length
      ? histories.map(history => ({ card: inherited, detail, history, multiple: histories.length > 1, child: false }))
      : [{ card: inherited, detail, history: null, child: false }]
  })
}

export function canExecuteCard(card) {
  return !card.closed_at && !card.children?.length && (card.remaining_sessions === null || Number(card.remaining_sessions) > 0)
}

export function isTreatmentComplete(card) {
  if (card.closed_at) return true
  if (card.children?.length) return card.children.every(isTreatmentComplete)
  return card.remaining_sessions != null && Number(card.remaining_sessions) <= 0
}

export function canCloseTreatment(card) {
  return !isTreatmentComplete(card) && treatmentCards(card).some(item => !item.closed_at && (item.total_sessions === null || item.remaining_sessions === null))
}

function hasTime(val) {
  if (!val) return false
  const s = String(val)
  return s.includes(':') && !s.includes('T00:00:00') && !s.includes(' 00:00:00')
}

export function treatmentHistoryGroups(card) {
  const childCards = treatmentCards(card)
  const childOrderMap = new Map()
  childCards.forEach((c, idx) => childOrderMap.set(c.id, idx))

  const allEntries = []
  for (const item of childCards) {
    for (const history of item.histories || []) {
      if (history.deleted_at) continue
      const day = dateOnly(history.execution_date)
      const branchId = history.branch_id
      const hasRealClock = hasTime(history.created_at) || hasTime(history.execution_date)
      const time = new Date(history.created_at || history.execution_date).getTime()
      allEntries.push({
        card: { ...item, customer_name: card.customer_name },
        history,
        day,
        branchId,
        time,
        hasRealClock,
        id: Number(history.id || 0)
      })
    }
  }

  // Sắp xếp: ngày giảm dần; nếu có giờ thực tế thì giờ giảm dần; ngược lại giữ thứ tự thẻ con
  allEntries.sort((a, b) => {
    if (b.day !== a.day) return b.day.localeCompare(a.day)
    if (a.hasRealClock && b.hasRealClock && b.time !== a.time) return b.time - a.time
    const orderA = childOrderMap.get(a.card.id) ?? 999
    const orderB = childOrderMap.get(b.card.id) ?? 999
    if (orderA !== orderB) return orderA - orderB
    return a.id - b.id
  })

  const groups = []
  for (const entry of allEntries) {
    const { card: itemCard, history, day, branchId, time, hasRealClock, id } = entry
    const sig = history.customer_signature_svg || null

    const match = groups.find(g => {
      if (g.day !== day || Number(g.branch_id) !== Number(branchId)) return false
      // Một lượt làm không thể có 2 lần cùng một liệu trình con
      if (g.sessions.some(s => s.card.id === itemCard.id)) return false
      if (sig && g.signatureSvg && sig !== g.signatureSvg) return false
      if (hasRealClock && g.hasRealClock) {
        const diff = Math.abs(time - g.anchorTime)
        if (diff > 120 * 1000) return false
      }
      return true
    })

    if (match) {
      match.sessions.push({ card: itemCard, history })
      if (history.branch_name && !match.branch_name) match.branch_name = history.branch_name
      if (sig && !match.signatureSvg) match.signatureSvg = sig
      if (id > match.maxId) match.maxId = id
      if (id < match.minId) match.minId = id
    } else {
      groups.push({
        key: `${day}:${branchId ?? 'unknown'}:${hasRealClock ? Math.round(time / 1000) : groups.length}`,
        day,
        branch_id: branchId,
        branch_name: history.branch_name,
        signatureSvg: sig,
        anchorTime: time,
        hasRealClock,
        firstCreatedAt: history.created_at || null,
        maxId: id,
        minId: id,
        sessions: [{ card: itemCard, history }]
      })
    }
  }

  // Nhóm mới nhất luôn ở đầu (ngày giảm dần, giờ giảm dần)
  groups.sort((a, b) => {
    if (b.day !== a.day) return b.day.localeCompare(a.day)
    if (a.hasRealClock && b.hasRealClock && b.anchorTime !== a.anchorTime) {
      return b.anchorTime - a.anchorTime
    }
    return 0
  })

  // Định danh key và sắp xếp các dịch vụ con bên trong mỗi nhóm theo thứ tự cấu hình cố định của liệu trình
  for (const g of groups) {
    g.sessions.sort((a, b) => {
      const orderA = childOrderMap.get(a.card.id) ?? 999
      const orderB = childOrderMap.get(b.card.id) ?? 999
      if (orderA !== orderB) return orderA - orderB
      return (a.card.product_name || '').localeCompare(b.card.product_name || '')
    })
  }

  return groups
}
